"""Outbound lending call business logic.

Two rules shape every method here.

**Plumbing never reaches the agent.** `operation_id` is generated by the tool
layer, not asked for in a signature, and replaying the same one returns the same
result instead of applying it twice.

**A failure carries its next step.** A tool that just says `ok: false` leaves the
model free to announce success anyway — that is what the interview agent recorded
as findings/#f-5. Every rejection here therefore states what is wrong *and* what
the agent should do about it, in words it can say out loud.
"""

from __future__ import annotations

import re
import unicodedata
import uuid
from datetime import datetime, timedelta, timezone
from typing import Any

from .data import Campaign, DataError, DataStore, IvrMenu, Lead
from .domain import AMBIGUOUS_CONSENT_PHRASES, DISPOSITIONS, CallSession
from .officers import OfficerCatalog
from .store import CallStore

OFFER_DECISION_MIN_DELAY_SECONDS = 2.5


def _ok(session: CallSession, **fields: Any) -> dict[str, Any]:
    return {"ok": True, "call_id": session.call_id, "state_version": session.state_version, **fields}


def _done(session: CallSession, _next_step: str = "", **fields: Any) -> dict[str, Any]:
    """A success that closes a stage.

    It reports `stage_complete` and nothing more. Telling the model where to go
    next from inside a tool result moves routing out of the graph and into the
    backend, and a stage's own prompt is the only place that decides it.
    """
    return _ok(session, stage_complete=True, **fields)


def _fail(error: str, next_step: str, **fields: Any) -> dict[str, Any]:
    # `next_step` here is how to recover *this* call, never where the call goes.
    return {"ok": False, "error": error, "next_step": next_step, **fields}


def _latest_event_age_seconds(session: CallSession, kind: str) -> float | None:
    event = next((item for item in reversed(session.events) if item.kind == kind), None)
    if event is None:
        return None
    timestamp = datetime.fromisoformat(event.ts)
    return (datetime.now(timezone.utc) - timestamp).total_seconds()


def _appointment_spoken_summary(session: CallSession) -> str:
    assert session.appointment is not None
    assert session.offer is not None
    appointment = session.appointment
    officer = appointment["officer"]
    mode = appointment["meeting_type"]
    location_description = (
        f" at {appointment['location']}" if mode == "onsite" else ""
    )
    return (
        f"Your {mode} appointment is booked for {appointment['when_text']}"
        f"{location_description} with {officer['full_name']}, {officer['title']}. "
        f"Your pre-offer is {session.offer['approved_amount_inr']} rupees for "
        f"{session.offer['tenure_months']} months at an annual rate of "
        f"{session.offer['annual_rate_percent']} percent."
    )


def _normalise_spoken_words(value: str) -> str:
    normalised = "".join(
        character
        if character.isspace()
        or unicodedata.category(character)[0] in {"L", "M", "N"}
        else " "
        for character in value.casefold()
    )
    return " ".join(normalised.split())


def _charge_response_is_objection(value: str) -> bool:
    markers = (
        "reduce",
        "reduced",
        "lower",
        "waive",
        "waived",
        "discount",
        "negotiate",
        "too high",
        "expensive",
        "why",
        "explain",
        "can this",
        "could this",
    )
    return any(marker in value for marker in markers)


def _charge_response_matches_decision(value: str, accepted: bool) -> bool:
    negative_accept = bool(
        re.search(r"\b(do not|don t|cannot|can t|won t|will not) accept\b", value)
    )
    english_affirmative = bool(
        re.search(r"\bi accept\b", value) and not negative_accept
    )
    english_negative = bool(
        re.search(r"\bi (reject|decline)\b", value)
        or negative_accept
    )
    hindi_negative = "मैं" in value and (
        "अस्वीकार" in value or ("स्वीकार" in value and "नहीं" in value)
    )
    hindi_affirmative = (
        "मैं" in value
        and "स्वीकार" in value
        and not hindi_negative
    )
    affirmative = english_affirmative or hindi_affirmative
    negative = english_negative or hindi_negative
    return affirmative and not negative if accepted else negative and not affirmative


def _decision_status(affirmative: bool, negative: bool) -> str:
    if affirmative == negative:
        return "unclear"
    return "explicit_yes" if affirmative else "explicit_no"


def _classify_charge_response(value: str) -> str:
    if _charge_response_is_objection(value):
        return "unclear"
    return _decision_status(
        _charge_response_matches_decision(value, accepted=True),
        _charge_response_matches_decision(value, accepted=False),
    )


def _standalone_farewell(value: str) -> bool:
    words = value.split()
    return bool(words) and all(
        word in {"bye", "goodbye", "good", "see", "you", "okay", "ok", "thanks", "thank"}
        for word in words
    )


def _explicit_end_request(value: str) -> bool:
    return any(
        marker in value
        for marker in (
            "end the call",
            "stop the call",
            "hang up",
            "stop calling",
            "do not call",
            "don t call",
            "i want to end",
            "i need to end",
        )
    )


def _disclosure_response_matches_decision(value: str, acknowledged: bool) -> bool:
    english_affirmative = bool(re.search(r"\bi confirm\b", value))
    english_negative = bool(
        re.search(r"\bi (do not confirm|refuse|decline)\b", value)
        or re.search(r"\b(do not|don t|cannot|can t|won t|will not) confirm\b", value)
        or _explicit_end_request(value)
    )
    hindi_negative = (
        "मैं असहमत" in value
        or "मैं अस्वीकार" in value
        or ("मैं पुष्टि" in value and "नहीं" in value)
        or ("मैं सहमत" in value and "नहीं" in value)
    )
    hindi_affirmative = (
        "मैं पुष्टि" in value or "मैं सहमत" in value
    ) and not hindi_negative
    affirmative = english_affirmative or hindi_affirmative
    negative = english_negative or hindi_negative
    return affirmative and not negative if acknowledged else negative and not affirmative


def _classify_disclosure_response(value: str) -> str:
    if _standalone_farewell(value):
        return "unclear"
    return _decision_status(
        _disclosure_response_matches_decision(value, acknowledged=True),
        _disclosure_response_matches_decision(value, acknowledged=False),
    )


def _offer_response_is_ambiguous(value: str) -> bool:
    markers = (
        "interest",
        "rate",
        "amount",
        "tenure",
        "period",
        "instalment",
        "installment",
        "emi",
        "more money",
        "lower",
        "reduce",
        "expensive",
        "too high",
        "what",
        "why",
        "how",
    )
    return any(marker in value for marker in markers)


def _offer_response_matches_decision(value: str, accepted: bool) -> bool:
    negative_want = bool(
        re.search(
            r"\b(do not|don t|cannot|can t|won t|will not) "
            r"(accept|take|want|proceed)\b",
            value,
        )
    )
    english_affirmative = bool(re.search(r"\bi accept\b", value)) and not negative_want
    english_negative = bool(
        re.search(r"\bi (reject|decline|am not interested)\b", value)
        or negative_want
    )
    hindi_negative = "मैं" in value and (
        "अस्वीकार" in value or ("स्वीकार" in value and "नहीं" in value)
    )
    hindi_affirmative = (
        "मैं" in value
        and "स्वीकार" in value
        and not hindi_negative
    )
    affirmative = english_affirmative or hindi_affirmative
    negative = english_negative or hindi_negative
    return affirmative and not negative if accepted else negative and not affirmative


def _classify_offer_response(value: str) -> str:
    if _offer_response_is_ambiguous(value):
        return "unclear"
    return _decision_status(
        _offer_response_matches_decision(value, accepted=True),
        _offer_response_matches_decision(value, accepted=False),
    )


def _bureau_response_matches_decision(value: str, consented: bool) -> bool:
    english_positive = bool(
        re.search(r"\bi consent\b", value)
        or re.search(r"\bi (give|grant) permission\b", value)
        or re.search(r"\bi permit\b", value)
    )
    english_negative = bool(
        re.search(r"\bi (do not|don t) consent\b", value)
        or re.search(r"\bi (do not|don t) (give|grant) permission\b", value)
        or re.search(r"\bi (refuse|decline)\b", value)
    )
    hindi_subject = "मैं" in value
    hindi_consent = "सहमति" in value or "अनुमति" in value
    hindi_negative = hindi_subject and (
        (hindi_consent and "नहीं" in value)
        or "मैं अस्वीकार" in value
        or "मैं मना" in value
    )
    hindi_positive = hindi_subject and hindi_consent and not hindi_negative
    positive = english_positive or hindi_positive
    negative = english_negative or hindi_negative
    return positive and not negative if consented else negative and not positive


def _classify_bureau_response(value: str) -> str:
    if value in AMBIGUOUS_CONSENT_PHRASES:
        return "unclear"
    return _decision_status(
        _bureau_response_matches_decision(value, consented=True),
        _bureau_response_matches_decision(value, consented=False),
    )


def _emi(principal: int, annual_rate_percent: float, months: int) -> int:
    """Standard reducing-balance EMI, rounded to whole rupees."""
    monthly_rate = annual_rate_percent / 12.0 / 100.0
    if monthly_rate <= 0:
        return round(principal / months)
    factor = (1 + monthly_rate) ** months
    return round(principal * monthly_rate * factor / (factor - 1))


def _max_principal(emi: int, annual_rate_percent: float, months: int) -> int:
    """Largest principal whose instalment still fits inside `emi`."""
    if emi <= 0 or months <= 0:
        return 0
    monthly_rate = annual_rate_percent / 12.0 / 100.0
    if monthly_rate <= 0:
        return int(emi * months)
    factor = (1 + monthly_rate) ** months
    return int(emi * (factor - 1) / (monthly_rate * factor))


_MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}

# People say a birthday out loud far more often than they spell it, and "first of
# January" is the normal form on a phone call.
_ONES = {
    "first": 1, "second": 2, "third": 3, "fourth": 4, "fifth": 5, "sixth": 6,
    "seventh": 7, "eighth": 8, "ninth": 9, "tenth": 10, "eleventh": 11,
    "twelfth": 12, "thirteenth": 13, "fourteenth": 14, "fifteenth": 15,
    "sixteenth": 16, "seventeenth": 17, "eighteenth": 18, "nineteenth": 19,
    "twentieth": 20, "thirtieth": 30,
}
_ONES_CARDINAL = {
    "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7,
    "eight": 8, "nine": 9, "ten": 10,
}


def _spoken_day(text: str) -> int | None:
    """A day of the month written out in words, including 'twenty first'."""
    words = re.findall(r"[a-z]+", text)
    for i, word in enumerate(words):
        if word in _ONES:
            return _ONES[word]
        if word in ("twenty", "thirty"):
            base = 20 if word == "twenty" else 30
            nxt = words[i + 1] if i + 1 < len(words) else ""
            if nxt in _ONES and _ONES[nxt] < 10:
                return base + _ONES[nxt]
            if nxt in _ONES_CARDINAL and _ONES_CARDINAL[nxt] < 10:
                return base + _ONES_CARDINAL[nxt]
            return base
    return None


def _month_day(spoken: str) -> tuple[int, int] | None:
    """Day and month out of however a date of birth was said, or None.

    The year is ignored on purpose: the caller is asked for a birthday over the
    phone, and people give it as "first of January" far more often than in full.
    """
    text = (spoken or "").strip().lower()
    if not text:
        return None
    iso = re.search(r"\b(\d{4})[-/](\d{1,2})[-/](\d{1,2})\b", text)
    if iso:
        return int(iso.group(2)), int(iso.group(3))
    name = re.search(r"\b([a-z]{3,9})\b", text)
    number = re.findall(r"\b(\d{1,2})(?:st|nd|rd|th)?\b", text)
    month = None
    for token in re.findall(r"[a-z]{3,9}", text):
        if token[:3] in _MONTHS:
            month = _MONTHS[token[:3]]
            break
    if month is not None:
        if number:
            return month, int(number[0])
        day = _spoken_day(text)
        if day is not None:
            return month, day
        return None
    if name and number:
        named = _MONTHS.get(name.group(1)[:3])
        if named is not None:
            return named, int(number[0])
    if len(number) >= 2:
        return int(number[0]), int(number[1])
    return None


class FinanceService:
    def __init__(
        self,
        data: DataStore,
        store: CallStore,
        officers: OfficerCatalog,
    ) -> None:
        self._data = data
        self._store = store
        self._officers = officers

    # ---------------------------------------------------------------- helpers

    def _session(self, call_id: str) -> CallSession | None:
        return self._store.get(call_id)

    def _replay(self, call_id: str, operation_id: str) -> dict[str, Any] | None:
        return self._store.cached_operation(call_id, operation_id)

    def _commit(
        self, session: CallSession, operation_id: str, result: dict[str, Any]
    ) -> dict[str, Any]:
        self._store.save(session)
        self._store.remember_operation(session.call_id, operation_id, result)
        return result

    def _campaign(self, session: CallSession) -> Campaign:
        return self._data.load_campaign(session.campaign_id)

    def _lead(self, session: CallSession) -> Lead:
        return self._data.load_lead(session.lead_id)

    def _menu(self, session: CallSession) -> IvrMenu:
        return self._data.load_ivr_menu(session.ivr_menu_id)

    def _require_open(self, call_id: str) -> tuple[CallSession | None, dict[str, Any] | None]:
        session = self._session(call_id)
        if session is None:
            return None, _fail(
                "unknown_call",
                "This call id does not exist. Start the call before doing anything else.",
                call_id=call_id,
            )
        if session.closed:
            return None, _fail(
                "call_already_closed",
                "An outcome has already been recorded for this call; say goodbye and stop.",
                call_id=call_id,
                disposition=session.disposition,
            )
        return session, None

    @staticmethod
    def _require_bureau_consent(session: CallSession) -> dict[str, Any] | None:
        if session.bureau_consent is True:
            return None
        return _fail(
            "bureau_consent_required",
            "Record the customer's explicit credit-bureau consent before offering a loan officer.",
        )

    # ------------------------------------------------------------ stage 0

    def start_call(
        self,
        lead_id: str,
        campaign_id: str,
        ivr_menu_id: str,
        operation_id: str,
        agent_persona_ref: str,
    ) -> dict[str, Any]:
        try:
            lead = self._data.load_lead(lead_id)
            campaign = self._data.load_campaign(campaign_id)
        except DataError as error:
            return _fail(
                "campaign_data_unavailable",
                "The campaign could not be loaded, so this call cannot go ahead. End it politely.",
                details=str(error),
            )
        session = CallSession(
            call_id=f"call-{uuid.uuid4().hex[:12]}",
            lead_id=lead.lead_id,
            campaign_id=campaign.campaign_id,
            ivr_menu_id=ivr_menu_id,
            agent_persona_ref=agent_persona_ref,
        )
        session.touch("call_started", f"dialled {lead.phone}")
        self._store.create(session)
        result = _ok(
            session,
            calling_first_name=lead.first_name,
            language=lead.language,
            relationship=lead.relationship,
            product_name=campaign.product_name,
        )
        self._store.remember_operation(session.call_id, operation_id, result)
        return result

    def send_dtmf(self, call_id: str, operation_id: str, digits: str) -> dict[str, Any]:
        cached = self._replay(call_id, operation_id)
        if cached is not None:
            return cached
        session, failure = self._require_open(call_id)
        if failure is not None:
            return failure
        assert session is not None
        if not session.ivr_position:
            session.answered_by = "ivr_menu"
            session.ivr_position = self._menu(session).entry_node_id
        pressed = "".join(character for character in (digits or "") if character in "0123456789*#")
        if not pressed:
            return _fail(
                "no_digits",
                "Nothing was pressed. Choose one option from the menu you just heard and press it.",
            )
        menu = self._menu(session)
        node = menu.node(session.ivr_position)
        if node is None:
            return _fail(
                "menu_position_lost",
                "The menu can no longer be followed. Stop trying and end the call cleanly.",
            )
        option = node.option_for(pressed)
        if option is None:
            session.dtmf_presses.append(pressed)
            session.touch("dtmf_rejected", pressed, menu_node=node.node_id)
            self._store.save(session)
            return _fail(
                "invalid_menu_choice",
                "That option is not on this menu. Listen to the options again and press a different one.",
                pressed=pressed,
                menu_node=node.node_id,
                available=[
                    {"digits": item.digits, "label": item.label} for item in node.options
                ],
            )
        session.dtmf_presses.append(pressed)
        session.ivr_position = option.goes_to
        session.touch("dtmf_accepted", pressed, goes_to=option.goes_to)
        return self._commit(
            session,
            operation_id,
            _ok(
                session,
                pressed=pressed,
                accepted=True,
                awaiting_acoustic_classification=True,
            ),
        )

    def leave_voicemail(
        self, call_id: str, operation_id: str, message_summary: str
    ) -> dict[str, Any]:
        cached = self._replay(call_id, operation_id)
        if cached is not None:
            return cached
        session, failure = self._require_open(call_id)
        if failure is not None:
            return failure
        assert session is not None
        summary = (message_summary or "").strip()
        if not summary:
            return _fail(
                "empty_message",
                "Nothing was said. Leave a short privacy-safe message saying that a calling assistant will try again.",
            )
        session.answered_by = "voicemail"
        session.voicemail_left = True
        session.touch("voicemail_left", summary[:200])
        return self._commit(session, operation_id, _ok(session, left=True))

    # ------------------------------------------------------------ stage 1-3

    def confirm_right_party(
        self, call_id: str, operation_id: str, date_of_birth: str
    ) -> dict[str, Any]:
        cached = self._replay(call_id, operation_id)
        if cached is not None:
            return cached
        session, failure = self._require_open(call_id)
        if failure is not None:
            return failure
        assert session is not None
        # Empty is the only way to say "not them": there is no separate flag for
        # the agent's own verdict, because its verdict is not what decides this.
        session.answered_by = "live_person"
        if not (date_of_birth or "").strip():
            session.right_party = False
            session.touch("right_party", "False")
            return self._commit(
                session,
                operation_id,
                _done(
                    session,
                    "This is not the person you are calling for. Say nothing "
                    "about the account and close the call politely.",
                    confirmed=False,
                ),
            )

        spoken = _month_day(date_of_birth)
        if spoken is None:
            return _fail(
                "date_of_birth_not_understood",
                "That was not a date. Ask them plainly for the day and month they "
                "were born, and pass back exactly what they say.",
            )
        if spoken != _month_day(self._lead(session).date_of_birth):
            # A mismatch is not a verdict: a misheard digit sounds exactly like an
            # impostor here, so it stays retryable and leaves right_party unset.
            session.touch("date_of_birth_mismatch", date_of_birth[:40])
            self._store.save(session)
            return _fail(
                "date_of_birth_does_not_match",
                "That is not the date of birth on this account. Tell them it does "
                "not match and ask them to say it again. Only if they cannot give "
                "the right one is this the wrong party.",
            )

        session.right_party = True
        session.touch("right_party", "True")
        return self._commit(
            session,
            operation_id,
            _done(
                session,
                "Identity is confirmed. You are done here — hand the call on and say "
                "nothing else yourself.",
                confirmed=True,
            ),
        )

    def record_disclosure(
        self, call_id: str, operation_id: str, spoken_words: str
    ) -> dict[str, Any]:
        cached = self._replay(call_id, operation_id)
        if cached is not None:
            return cached
        session, failure = self._require_open(call_id)
        if failure is not None:
            return failure
        assert session is not None
        if session.right_party is not True:
            return _fail(
                "right_party_not_confirmed",
                "You have not established that this is the right person. Ask that first.",
            )
        phrase = (spoken_words or "").strip()
        normalised = _normalise_spoken_words(phrase)
        decision_status = _classify_disclosure_response(normalised)
        if not phrase or decision_status == "unclear":
            session.touch(
                "disclosure_response_not_explicit",
                normalised[:120],
            )
            self._store.save(session)
            return _fail(
                "disclosure_response_not_explicit",
                (
                    "Bare yes, yeah, a standalone farewell, or another ambiguous "
                    "phrase is not a decision. Ask them to say 'I confirm' or "
                    "'I decline'. Confirm end intent separately if they say bye."
                ),
                heard=phrase,
                decision_status="unclear",
            )
        acknowledged = decision_status == "explicit_yes"
        session.disclosure_ack = acknowledged
        session.touch(
            "disclosure", str(acknowledged), heard=phrase[:120]
        )
        return self._commit(
            session,
            operation_id,
            _done(
                session,
                "They have agreed to continue. You are done here — hand the call "
                "on and say nothing else yourself."
                if acknowledged
                else "They did not agree to continue. Close the call politely.",
                acknowledged=acknowledged,
                decision_status=decision_status,
            ),
        )

    # -------------------------------------------------------- stage 2: quoting

    def _require_identified(
        self, call_id: str
    ) -> tuple[CallSession | None, dict[str, Any] | None]:
        """Enough to quote the offer: the intended borrower is identified.

        Deliberately does not require interest — nobody can say whether they want
        a loan before they have been told the amount and the rate.
        """
        session, failure = self._require_open(call_id)
        if failure is not None:
            return None, failure
        assert session is not None
        if session.right_party is not True:
            return None, _fail(
                "right_party_not_confirmed",
                "You have not established that this is the right person. Ask that first.",
            )
        return session, None

    # ------------------------------------------------------------------------
    # The offer stage is two calls: price it, then record what they decided.
    #
    # It used to be ten — four capture tools writing one slot each, a status
    # read to find out which slot was still empty, an eligibility check that
    # refused until all four were filled, and two separate accept tools. That
    # shape made the model keep a form, and a customer who argued for a
    # different figure forced it to rewrite the form and re-run the check. The
    # figures are all negotiable, so the form was the wrong model:
    # `calculate_indicative_loan_offer` takes whatever is on the table now and
    # prices it, and re-pricing is the normal move rather than an error path.
    # ------------------------------------------------------------------------

    def _take_amount(
        self, session: CallSession, campaign: Campaign, value: Any
    ) -> dict[str, Any] | None:
        if value is None:
            return None
        try:
            amount = int(value)
        except (TypeError, ValueError):
            return _fail(
                "amount_not_a_number",
                "That was not a figure. Ask them for the amount again in rupees.",
            )
        if not campaign.min_amount_inr <= amount <= campaign.max_amount_inr:
            session.touch("amount_rejected", str(amount))
            return _fail(
                "amount_out_of_range",
                (
                    "That amount is outside what this offer can do. Tell them the range "
                    f"is {campaign.min_amount_inr} to {campaign.max_amount_inr} rupees "
                    "and ask them for a figure again."
                ),
                heard=amount,
                min_amount_inr=campaign.min_amount_inr,
                max_amount_inr=campaign.max_amount_inr,
            )
        session.touch("amount", str(amount), previous=session.loan_amount_inr)
        session.loan_amount_inr = amount
        return None

    def _take_tenure(
        self, session: CallSession, campaign: Campaign, value: Any
    ) -> dict[str, Any] | None:
        if value is None:
            return None
        try:
            months = int(value)
        except (TypeError, ValueError):
            return _fail(
                "tenure_not_a_number",
                "That was not a number of months. Ask them again how long they want it over.",
            )
        if not campaign.tenure_is_offered(months):
            session.touch("tenure_rejected", str(months))
            return _fail(
                "tenure_not_offered",
                (
                    "That period is not one this offer runs for. Tell them the choices are "
                    f"{', '.join(str(item) for item in campaign.allowed_tenures_months)} months "
                    "and ask which one they want."
                ),
                heard=months,
                allowed_tenures_months=list(campaign.allowed_tenures_months),
            )
        session.touch("tenure", str(months), previous=session.tenure_months)
        session.tenure_months = months
        return None

    def _take_income(self, session: CallSession, value: Any) -> dict[str, Any] | None:
        if value is None:
            return None
        try:
            amount = int(value)
        except (TypeError, ValueError):
            return _fail(
                "income_not_a_number",
                "That was not a figure. Ask them again what they earn in a month.",
            )
        if amount <= 0 or amount > 10_000_000:
            session.touch("income_rejected", str(amount))
            return _fail(
                "income_not_plausible",
                "That monthly figure does not look right. Read it back to them and ask them to confirm it.",
                heard=amount,
            )
        session.touch("income", str(amount), previous=session.monthly_income_inr)
        session.monthly_income_inr = amount
        return None

    def _take_collateral(self, session: CallSession, value: Any) -> dict[str, Any] | None:
        if value is None:
            return None
        try:
            amount = int(value)
        except (TypeError, ValueError):
            return _fail(
                "collateral_not_a_number",
                "That was not a figure. Ask them again what the security is worth.",
            )
        if amount < 0 or amount > 100_000_000:
            session.touch("collateral_rejected", str(amount))
            return _fail(
                "collateral_not_plausible",
                "That figure is not usable. Ask them again what the security is worth.",
                heard=amount,
            )
        session.touch("collateral", str(amount), previous=session.collateral_value_inr)
        session.collateral_value_inr = amount
        return None

    def _still_needed(self, session: CallSession, lead: Lead) -> list[str]:
        """What is missing for the amount currently on the table.

        Security is only asked for once the amount has gone past what the
        pre-approved limit covers on its own — asking a customer who took the
        pre-approved figure what their house is worth is a question with no
        purpose, and every purposeless question is somewhere to lose the call.
        """
        need: list[str] = []
        if session.tenure_months is None:
            need.append("tenure_months")
        if session.monthly_income_inr is None:
            need.append("monthly_income_inr")
        if (
            session.collateral_value_inr is None
            and (session.loan_amount_inr or 0) > lead.preapproved_limit_inr
        ):
            need.append("collateral_value_inr")
        return need

    def _working_figures(self, session: CallSession) -> dict[str, Any]:
        return {
            "amount_inr": session.loan_amount_inr,
            "tenure_months": session.tenure_months,
            "monthly_income_inr": session.monthly_income_inr,
            "collateral_value_inr": session.collateral_value_inr or 0,
        }

    def calculate_indicative_loan_offer(
        self,
        call_id: str,
        operation_id: str,
        amount_inr: Any = None,
        tenure_months: Any = None,
        monthly_income_inr: Any = None,
        collateral_value_inr: Any = None,
    ) -> dict[str, Any]:
        """Price the loan from whatever is known, and say what would change it.

        Records no decision, so calling it again with a changed figure is the
        normal move rather than a correction.
        """
        cached = self._replay(call_id, operation_id)
        if cached is not None:
            return cached
        session, failure = self._require_identified(call_id)
        if failure is not None:
            return failure
        assert session is not None
        campaign = self._campaign(session)
        lead = self._lead(session)

        # Validated one figure at a time, before anything is priced: a misheard
        # number has to come back as a named error, not as a quote nobody can
        # tell was wrong.
        for rejected in (
            self._take_amount(session, campaign, amount_inr),
            self._take_tenure(session, campaign, tenure_months),
            self._take_income(session, monthly_income_inr),
            self._take_collateral(session, collateral_value_inr),
        ):
            if rejected is not None:
                self._store.save(session)
                return rejected

        if session.pitched_amount_inr is None:
            session.pitched_amount_inr = min(
                lead.preapproved_limit_inr, campaign.max_amount_inr
            )
        # On this campaign the amount is offered, not asked for, so the
        # pre-approved figure stands until they argue for a different one.
        if session.loan_amount_inr is None:
            session.loan_amount_inr = session.pitched_amount_inr

        headline = {
            "preapproved_amount_inr": session.pitched_amount_inr,
            "product_name": campaign.product_name,
            "min_amount_inr": campaign.min_amount_inr,
            "max_amount_inr": campaign.max_amount_inr,
            "amount_change_policy": {
                "unnamed_change": (
                    "If the customer asks for more, less, or an increase without "
                    "naming a figure, ask for the exact target amount. Do not repeat "
                    "the current amount and do not ask them to accept it."
                ),
                "above_preapproved": (
                    "An amount above the pre-approved figure is not automatically "
                    "rejected. Send the requested amount to this tool, then ask for "
                    "collateral only if need includes collateral_value_inr."
                ),
            },
            "allowed_tenures_months": sorted(campaign.allowed_tenures_months),
            "indicative_annual_rate_percent": campaign.rate_for_amount(
                session.loan_amount_inr
            ),
            "rate_tiers": [
                {"up_to_amount_inr": ceiling, "annual_rate_percent": rate}
                for ceiling, rate in campaign.rate_tiers
            ],
            "rate_negotiable": campaign.rate_negotiable,
            "indicative": True,
        }
        if session.tenure_months is None:
            default_tenure = campaign.default_tenure_months
            default_rate = campaign.rate_for_amount(session.loan_amount_inr)
            headline["starting_illustration"] = {
                "amount_inr": session.loan_amount_inr,
                "tenure_months": default_tenure,
                "annual_rate_percent": default_rate,
                "monthly_emi_inr": _emi(
                    session.loan_amount_inr, default_rate, default_tenure
                ),
                "indicative": True,
                "customer_confirmed": False,
            }

        need = self._still_needed(session, lead)
        if need:
            session.touch("quote_needs", ",".join(need))
            return self._commit(
                session,
                operation_id,
                _ok(
                    session,
                    using=self._working_figures(session),
                    need=need,
                    priced=False,
                    **headline,
                ),
            )

        assert session.loan_amount_inr is not None
        assert session.tenure_months is not None
        assert session.monthly_income_inr is not None
        session.eligibility_checked = True
        affordable_emi = int(session.monthly_income_inr * campaign.max_foir)
        ranges = self._single_variable_ranges(session, campaign, lead, affordable_emi)
        common = {
            "using": self._working_figures(session),
            "need": [],
            "priced": True,
            "ranges_with_others_unchanged": ranges,
            **headline,
        }

        if session.monthly_income_inr < campaign.min_monthly_income_inr:
            session.offer = None
            session.touch("quote", "declined_income")
            return self._commit(
                session,
                operation_id,
                _ok(
                    session,
                    eligible=False,
                    reason="monthly_income_below_minimum",
                    spoken_reason="the monthly income for this offer has to be higher than what they told you",
                    minimum_monthly_income_inr=campaign.min_monthly_income_inr,
                    **common,
                ),
            )

        ceiling = min(session.loan_amount_inr, self._lending_ceiling(session, campaign, lead))
        approved = ceiling
        while approved >= campaign.min_amount_inr:
            if _emi(approved, campaign.rate_for_amount(approved), session.tenure_months) <= affordable_emi:
                break
            approved -= 10_000
        if approved < campaign.min_amount_inr:
            session.offer = None
            session.touch("quote", "declined_affordability")
            return self._commit(
                session,
                operation_id,
                _ok(
                    session,
                    eligible=False,
                    reason="instalment_exceeds_affordability",
                    spoken_reason="the monthly instalment would be too high against what they earn",
                    max_amount_available_inr=ranges["loan_amount_inr"]["max"],
                    minimum_amount_inr=campaign.min_amount_inr,
                    affordable_instalment_inr=affordable_emi,
                    longer_tenures_months=ranges["tenure_months"][
                        "that_would_work_for_this_amount"
                    ],
                    a_longer_period_would_allow_more=bool(
                        ranges["tenure_months"]["that_would_work_for_this_amount"]
                    ),
                    **common,
                ),
            )

        offer = {
            "approved_amount_inr": approved,
            "tenure_months": session.tenure_months,
            "annual_rate_percent": campaign.rate_for_amount(approved),
            "monthly_emi_inr": _emi(
                approved, campaign.rate_for_amount(approved), session.tenure_months
            ),
            "indicative": True,
            "reduced_from_requested": approved < session.loan_amount_inr,
        }
        session.offer = offer
        session.touch("quote", f"offer {approved}")
        return self._commit(
            session,
            operation_id,
            _ok(
                session,
                eligible=True,
                offer=offer,
                negotiation_policy=(
                    "You may not invent a rate. The rate is set by how much is "
                    "borrowed: see rate_tiers. A smaller amount is priced at a "
                    "lower rate, so borrowing less is a real answer to a "
                    "complaint about the rate, and so is a longer period, which "
                    "lowers the instalment. Send any figure they argue for back "
                    "through this tool and say only what comes back. If their "
                    "request remains outside the supported result, explain that "
                    "the current flow cannot provide it and that a loan officer "
                    "can discuss details and may have special offers. Never "
                    "promise an exception or discount."
                ),                internal_do_not_disclose={
                    "floor_rate_percent": campaign.internal_floor_rate_percent,
                    "note": "pricing authority; never say this number out loud",
                },
                **self._negotiation_room(session, campaign, lead, approved, affordable_emi),
                **common,
            ),
        )

    def record_customer_offer_decision(
        self,
        call_id: str,
        operation_id: str,
        spoken_words: str,
        note: str = "",
    ) -> dict[str, Any]:
        """The offer stage's only write, and its only way out."""
        cached = self._replay(call_id, operation_id)
        if cached is not None:
            return cached
        session, failure = self._require_open(call_id)
        if failure is not None:
            return failure
        assert session is not None
        phrase = (spoken_words or "").strip()
        normalised = _normalise_spoken_words(phrase)
        decision_status = _classify_offer_response(normalised)
        if not phrase or decision_status == "unclear":
            session.touch(
                "offer_decision_not_explicit",
                normalised[:120],
            )
            self._store.save(session)
            return _fail(
                "offer_decision_not_explicit",
                (
                    "Interest, a rate or amount question, a counter-offer, and an "
                    "ambiguous phrase such as bare yes or yeah are not acceptance "
                    "or decline. Answer or reprice the issue, then ask them to say "
                    "'I accept' or 'I decline'."
                ),
                heard=phrase,
                decision_status="unclear",
            )
        quote_age = _latest_event_age_seconds(session, "quote")
        if quote_age is None or session.offer is None:
            return _fail(
                "no_quote_to_accept",
                "Finish the complete pre-offer before asking for a decision.",
            )
        if quote_age < OFFER_DECISION_MIN_DELAY_SECONDS:
            return _fail(
                "offer_decision_too_soon",
                (
                    "Stop this response without more speech or tools. Wait for "
                    "new customer audio before recording acceptance or decline."
                ),
                minimum_delay_seconds=OFFER_DECISION_MIN_DELAY_SECONDS,
            )
        session.offer_note = (note or "").strip()[:300]
        if decision_status == "explicit_no":
            session.offer_accepted = False
            session.touch(
                "offer_declined", session.offer_note, heard=phrase[:120]
            )
            return self._commit(
                session,
                operation_id,
                _done(
                    session,
                    decision="declined",
                    decision_status=decision_status,
                    offer_accepted=False,
                ),
            )
        # Accepting something nobody was told is how a call ends up on record as
        # agreed terms the customer never heard. See issues/13.
        session.offer_accepted = True
        session.touch(
            "offer_accepted",
            str(session.offer.get("approved_amount_inr")),
            heard=phrase[:120],
        )
        return self._commit(
            session,
            operation_id,
            _done(
                session,
                decision="accepted",
                decision_status=decision_status,
                offer_accepted=True,
                offer=session.offer,
                qualified_lead=session.is_qualified_lead,
            ),
        )

    # ----------------------------------------------------- stage 3: charges

    def present_charges(self, call_id: str) -> dict[str, Any]:
        session, failure = self._require_open(call_id)
        if failure is not None:
            return failure
        assert session is not None
        if not session.offer:
            return _fail(
                "no_offer_yet",
                "There is no figure to charge against yet. Work out the offer first.",
            )
        if session.offer_accepted is not True:
            return _fail(
                "offer_not_accepted",
                "The customer has not accepted the indicative offer yet. Settle the offer decision before disclosing charges.",
            )
        campaign = self._campaign(session)
        amount = int(session.offer["approved_amount_inr"])
        fee = campaign.processing_fee_inr(amount)
        total_upfront = fee + campaign.insurance_premium_inr
        if not session.charges_presented:
            session.charges_presented = True
            session.touch(
                "charges_presented",
                str(total_upfront),
                processing_fee_inr=fee,
                insurance_premium_inr=campaign.insurance_premium_inr,
            )
            self._store.save(session)
        return _done(
            session,
            charges_presented=True,
            processing_fee_inr=fee,
            processing_fee_percent=campaign.processing_fee_percent,
            insurance_premium_inr=campaign.insurance_premium_inr,
            total_upfront_inr=total_upfront,
            deducted_from_disbursal=True,
            charges_negotiable=False,
            customer_explanation=(
                "These are the applicable processing fee and insurance premium "
                "for this offer. They are deducted from the disbursal amount and "
                "cannot be reduced in this flow. If the customer keeps requesting "
                "an exception, say a loan officer may have special offers to "
                "discuss at the appointment, but do not promise a discount or waiver."
            ),
        )

    def record_charges_response(
        self, call_id: str, operation_id: str, spoken_words: str
    ) -> dict[str, Any]:
        cached = self._replay(call_id, operation_id)
        if cached is not None:
            return cached
        session, failure = self._require_open(call_id)
        if failure is not None:
            return failure
        assert session is not None
        if session.offer_accepted is not True:
            return _fail(
                "offer_not_accepted",
                "They have not accepted the quote yet. Settle that before the fees.",
            )
        phrase = (spoken_words or "").strip()
        normalised = _normalise_spoken_words(phrase)
        decision_status = _classify_charge_response(normalised)
        if not phrase or decision_status == "unclear":
            session.touch(
                "charges_response_not_explicit",
                normalised[:120],
            )
            self._store.save(session)
            return _fail(
                "charges_response_not_explicit",
                (
                    "A question, objection, or request to reduce charges is not a "
                    "rejection. Explain the fixed charges using present_charges, "
                    "then ask them to say 'I accept' or 'I decline'. Bare yes or "
                    "yeah is not enough."
                ),
                heard=phrase,
                decision_status="unclear",
            )
        accepted = decision_status == "explicit_yes"
        session.charges_accepted = accepted
        session.touch("charges", str(accepted), heard=phrase[:120])
        return self._commit(
            session,
            operation_id,
            _ok(
                session,
                charges_accepted=accepted,
                decision_status=decision_status,
            ),
        )

    # ----------------------------------------------- stage 4: bureau consent

    def capture_bureau_consent(
        self, call_id: str, operation_id: str, spoken_words: str
    ) -> dict[str, Any]:
        cached = self._replay(call_id, operation_id)
        if cached is not None:
            return cached
        session, failure = self._require_open(call_id)
        if failure is not None:
            return failure
        assert session is not None
        if session.offer_accepted is not True:
            return _fail(
                "offer_not_accepted",
                "They have not accepted the quote yet. A credit check cannot be asked for before that.",
            )
        phrase = (spoken_words or "").strip()
        normalised = _normalise_spoken_words(phrase)
        decision_status = _classify_bureau_response(normalised)
        if not phrase:
            error = "consent_not_evidenced"
        elif decision_status == "unclear":
            error = "consent_not_explicit"
        else:
            error = ""
        if error:
            session.bureau_consent_unclear_attempts += 1
            attempts = session.bureau_consent_unclear_attempts
            session.touch(
                "bureau_consent_unclear",
                normalised,
                attempts=attempts,
            )
            self._store.save(session)
            return _fail(
                error,
                (
                    "Bare yes, yeah, no, and fillers are not auditable consent. Ask "
                    "them to say 'I consent' or 'I decline'. Do not proceed unless "
                    "this tool returns an explicit decision."
                ),
                heard=phrase,
                decision_status="unclear",
                attempts=attempts,
                attempts_remaining=max(0, 3 - attempts),
                retry_exhausted=attempts >= 3,
            )
        consented = decision_status == "explicit_yes"
        session.bureau_consent = consented
        session.bureau_consent_phrase = phrase[:200]
        session.touch("bureau_consent", str(consented).lower(), heard=phrase[:120])
        return self._commit(
            session,
            operation_id,
            _ok(
                session,
                consented=consented,
                decision_status=decision_status,
                recorded_words=phrase[:200],
            ),
        )

    # -------------------------------------------------------- pricing policy

    def _lending_ceiling(
        self, session: CallSession, campaign: Campaign, lead: Lead
    ) -> int:
        """The most this customer can be lent, before affordability is applied.

        The pre-approved figure is what needs no security, not a hard cap: asking
        for more is a normal negotiation and security is what funds it. Capping
        at the pre-approved figure left the agent with nothing to concede, so a
        customer who could comfortably afford more was simply refused.
        """
        collateral = session.collateral_value_inr or 0
        return min(campaign.max_amount_inr, lead.preapproved_limit_inr + collateral)

    def _negotiation_room(
        self,
        session: CallSession,
        campaign: Campaign,
        lead: Lead,
        approved: int,
        affordable_emi: int,
    ) -> dict[str, Any]:
        """How far each lever can still move before risk policy stops it.

        The agent must not work this out itself, and must not keep arguing once a
        lever is at its limit — so the limits are computed here and reported as
        plain booleans it can act on.
        """
        assert session.tenure_months is not None
        tenures = sorted(campaign.allowed_tenures_months)
        longer = [t for t in tenures if t > session.tenure_months]
        headroom = self._lending_ceiling(session, campaign, lead)

        # A longer period lowers the instalment, so it is the lever that can free
        # up room; whether it actually helps depends on affordability.
        tenure_helps = any(
            _emi(headroom, campaign.rate_for_amount(headroom), t) <= affordable_emi
            for t in longer
        )
        wanted = session.loan_amount_inr or 0
        collateral_gap = max(0, min(wanted, campaign.max_amount_inr) - headroom)
        return {
            "rate_at_floor": not campaign.rate_negotiable,
            "amount_at_ceiling": approved >= headroom,
            "tenure_at_maximum": not longer,
            "max_amount_available_inr": headroom,
            "longer_tenures_months": longer,
            "a_longer_period_would_allow_more": tenure_helps,
            # what would unlock the amount they actually asked for
            "extra_security_needed_inr": collateral_gap,
            "at_boundary": (
                not campaign.rate_negotiable and approved >= headroom and not longer
            ),
        }

    def _single_variable_ranges(
        self,
        session: CallSession,
        campaign: Campaign,
        lead: Lead,
        affordable_emi: int,
    ) -> dict[str, Any]:
        """What each figure would have to become, with the other three left alone.

        A refusal is only useful if the agent can say what would change it, so
        every lever is reported as its own one-variable range against the same
        risk policy. The agent never derives these itself.
        """
        amount = session.loan_amount_inr or 0
        months = session.tenure_months or 0
        rate = campaign.rate_for_amount(amount)
        ceiling = self._lending_ceiling(session, campaign, lead)
        tiers = campaign.rate_tiers or (
            (campaign.max_amount_inr, campaign.annual_rate_percent),
        )

        # The rate is priced off the amount, so the affordable principal has to be
        # solved inside each tier rather than once at a single rate.
        amount_max = 0
        for tier_ceiling, tier_rate in tiers:
            amount_max = max(
                amount_max,
                min(tier_ceiling, ceiling, _max_principal(affordable_emi, tier_rate, months)),
            )
        tenures_that_work = [
            t
            for t in sorted(campaign.allowed_tenures_months)
            if amount
            and _emi(
                min(amount, ceiling), campaign.rate_for_amount(min(amount, ceiling)), t
            )
            <= affordable_emi
        ]
        required_emi = _emi(amount, rate, months) if amount and months else 0
        return {
            "loan_amount_inr": {
                "min": campaign.min_amount_inr,
                "max": max(0, amount_max),
                "achievable": amount_max >= campaign.min_amount_inr,
            },
            "tenure_months": {
                "allowed": sorted(campaign.allowed_tenures_months),
                "that_would_work_for_this_amount": tenures_that_work,
                "achievable": bool(tenures_that_work),
            },
            "annual_rate_percent": {
                "current": rate,
                "set_by": "the amount borrowed",
                "negotiable": campaign.rate_negotiable,
                "tiers": [
                    {"up_to_amount_inr": tier_ceiling, "annual_rate_percent": tier_rate}
                    for tier_ceiling, tier_rate in tiers
                ],
                "lowest_available": min(tier_rate for _, tier_rate in tiers),
            },
            "monthly_income_inr": {
                "current": session.monthly_income_inr,
                "minimum_for_this_offer": (
                    int(required_emi / campaign.max_foir) if required_emi else 0
                ),
                "campaign_minimum": campaign.min_monthly_income_inr,
            },
            "collateral_value_inr": {
                "current": session.collateral_value_inr or 0,
                "minimum_for_this_amount": max(
                    0,
                    min(amount, campaign.max_amount_inr) - lead.preapproved_limit_inr,
                ),
            },
        }

    def search_loan_officer(
        self,
        call_id: str,
        operation_id: str,
        spoken_name: str,
        also_heard: list[str] | None = None,
    ) -> dict[str, Any]:
        cached = self._replay(call_id, operation_id)
        if cached is not None:
            return cached
        session, failure = self._require_open(call_id)
        if failure is not None:
            return failure
        assert session is not None
        consent_failure = self._require_bureau_consent(session)
        if consent_failure is not None:
            return consent_failure
        outcome = self._officers.search(spoken_name, also_heard)
        matches = list(outcome.get("matches") or [])
        session.last_officer_match_ids = [
            str(match["officer_id"]) for match in matches
        ]
        session.selected_officer_id = ""
        session.officer_selection_mode = ""
        session.touch(
            "officer_search",
            str(outcome.get("query") or spoken_name)[:120],
            status=outcome.get("status"),
            match_count=len(matches),
        )
        return self._commit(
            session,
            operation_id,
            _ok(
                session,
                status=outcome.get("status"),
                query=outcome.get("query", ""),
                queries=outcome.get("queries", []),
                normalized_query=outcome.get("normalized_query", ""),
                matches=matches,
                match_count=len(matches),
                reason=outcome.get("reason"),
            ),
        )

    def confirm_loan_officer(
        self,
        call_id: str,
        operation_id: str,
        officer_id: str,
    ) -> dict[str, Any]:
        cached = self._replay(call_id, operation_id)
        if cached is not None:
            return cached
        session, failure = self._require_open(call_id)
        if failure is not None:
            return failure
        assert session is not None
        consent_failure = self._require_bureau_consent(session)
        if consent_failure is not None:
            return consent_failure
        if officer_id not in session.last_officer_match_ids:
            return _fail(
                "officer_not_in_last_search",
                "Search again and use only an officer the latest search returned.",
            )
        officer = self._officers.by_id(officer_id)
        if officer is None:
            return _fail(
                "officer_not_found",
                "That officer is no longer in the directory. Search again.",
            )
        if officer.status != "available":
            return _fail(
                "officer_unavailable",
                "That officer is not available. Ask them to choose another officer or use automatic assignment.",
                officer=officer.public(),
            )
        session.selected_officer_id = officer.officer_id
        session.officer_selection_mode = "caller_selected"
        session.touch("officer_selected", officer.full_name, mode="caller_selected")
        return self._commit(
            session,
            operation_id,
            _ok(
                session,
                selected=True,
                selection_mode=session.officer_selection_mode,
                officer=officer.public(),
            ),
        )

    def auto_assign_loan_officer(
        self,
        call_id: str,
        operation_id: str,
    ) -> dict[str, Any]:
        cached = self._replay(call_id, operation_id)
        if cached is not None:
            return cached
        session, failure = self._require_open(call_id)
        if failure is not None:
            return failure
        assert session is not None
        consent_failure = self._require_bureau_consent(session)
        if consent_failure is not None:
            return consent_failure
        officer = self._officers.auto_assign(call_id)
        if officer is None:
            return _fail(
                "no_officer_available",
                "No loan officer is available. Apologise and close the call without promising a transfer.",
            )
        session.last_officer_match_ids = []
        session.selected_officer_id = officer.officer_id
        session.officer_selection_mode = "automatic"
        session.touch("officer_selected", officer.full_name, mode="automatic")
        return self._commit(
            session,
            operation_id,
            _ok(
                session,
                selected=True,
                selection_mode=session.officer_selection_mode,
                officer=officer.public(),
            ),
        )

    def transfer_to_loan_officer(
        self, call_id: str, operation_id: str, reason: str
    ) -> dict[str, Any]:
        cached = self._replay(call_id, operation_id)
        if cached is not None:
            return cached
        session, failure = self._require_open(call_id)
        if failure is not None:
            return failure
        assert session is not None
        if not session.offer:
            return _fail(
                "no_offer_to_transfer",
                "There is no offer on this call yet, so there is nothing to hand over. Work it out first.",
            )
        consent_failure = self._require_bureau_consent(session)
        if consent_failure is not None:
            return consent_failure
        if not session.selected_officer_id:
            return _fail(
                "officer_not_selected",
                "Ask whether they want a specific loan officer or automatic assignment, then complete that selection before transferring.",
            )
        officer = self._officers.by_id(session.selected_officer_id)
        if officer is None or officer.status != "available":
            session.selected_officer_id = ""
            session.officer_selection_mode = ""
            self._store.save(session)
            return _fail(
                "officer_unavailable",
                "The selected officer is no longer available. Search again or use automatic assignment.",
            )
        session.transferred = True
        session.disposition = "transferred"
        session.touch(
            "transferred",
            officer.full_name,
            reason=(reason or "").strip()[:200],
            selection_mode=session.officer_selection_mode,
        )
        return self._commit(
            session,
            operation_id,
            _ok(
                session,
                transferred=True,
                disposition="transferred",
                selection_mode=session.officer_selection_mode,
                officer=officer.public(),
            ),
        )

    # ------------------------------------------------------------ wrap up

    def schedule_callback(
        self,
        call_id: str,
        operation_id: str,
        when_text: str,
        meeting_type: str = "phone",
        location: str = "",
    ) -> dict[str, Any]:
        cached = self._replay(call_id, operation_id)
        if cached is not None:
            return cached
        session, failure = self._require_open(call_id)
        if failure is not None:
            return failure
        assert session is not None
        text = (when_text or "").strip()
        if not text:
            return _fail(
                "no_time_given",
                "No time was given. Ask them when would suit them better.",
            )
        mode = (meeting_type or "").strip().lower().replace("-", "")
        if mode not in {"phone", "onsite"}:
            return _fail(
                "unknown_meeting_type",
                "Ask whether they prefer a phone appointment or an onsite meeting.",
                allowed=["phone", "onsite"],
            )
        place = (location or "").strip()
        if mode == "onsite" and not place:
            return _fail(
                "onsite_location_required",
                "Ask where the onsite meeting should take place, then try again.",
            )

        when_value = text[:120]
        qualified = session.offer_accepted is True
        if not qualified:
            if mode != "phone":
                return _fail(
                    "officer_appointment_not_ready",
                    "An onsite officer meeting can be booked only after the offer is accepted.",
                )
            session.callback_at = when_value
            session.touch("callback", session.callback_at)
            return self._commit(
                session, operation_id, _ok(session, callback_at=session.callback_at)
            )

        officer = (
            self._officers.by_id(session.selected_officer_id)
            if session.selected_officer_id
            else None
        )
        if officer is None or officer.status != "available":
            officer = self._officers.auto_assign(call_id)
        if officer is None:
            return _fail(
                "no_officer_available",
                "No loan officer is available for an appointment. Apologise and ask for a phone callback time instead.",
            )

        session.selected_officer_id = officer.officer_id
        session.officer_selection_mode = "automatic"
        session.callback_at = when_value
        session.appointment = {
            "when_text": session.callback_at,
            "meeting_type": mode,
            "location": place[:160] if mode == "onsite" else "",
            "officer": officer.public(),
        }
        session.touch(
            "officer_appointment",
            session.callback_at,
            meeting_type=mode,
            location=session.appointment["location"],
            officer_id=officer.officer_id,
        )
        session.disposition = "qualified_lead"
        session.touch(
            "disposition",
            "qualified_lead",
            note=f"{mode} appointment booked for {session.callback_at}",
        )
        spoken_summary = _appointment_spoken_summary(session)
        return self._commit(
            session,
            operation_id,
            _ok(
                session,
                recorded=True,
                disposition=session.disposition,
                spoken_summary=spoken_summary,
            ),
        )

    def set_disposition(
        self,
        call_id: str,
        operation_id: str,
        code: str,
        note: str,
        spoken_words: str = "",
    ) -> dict[str, Any]:
        cached = self._replay(call_id, operation_id)
        if cached is not None:
            return cached
        session = self._session(call_id)
        if session is None:
            return _fail("unknown_call", "This call id does not exist.", call_id=call_id)
        value = (code or "").strip().lower()
        if value not in DISPOSITIONS:
            return _fail(
                "unknown_disposition",
                "That is not an outcome this campaign records. Choose one of the listed outcomes.",
                allowed=list(DISPOSITIONS),
            )
        if value == "qualified_lead" and not (
            session.offer_accepted is True
            and session.appointment is not None
        ):
            return _fail(
                "qualified_lead_not_ready",
                "Complete the loan-officer appointment before recording a qualified lead.",
                requires=[
                    "accepted offer",
                    "loan-officer appointment",
                ],
            )
        if value == "customer_ended":
            evidence = _normalise_spoken_words((spoken_words or "").strip())
            if not _explicit_end_request(evidence):
                return _fail(
                    "customer_end_not_confirmed",
                    (
                        "A standalone bye or goodbye is not enough to end the call. "
                        "Ask whether they want to end it and record customer_ended "
                        "only after they explicitly say 'end the call' or 'stop the call'."
                    ),
                    heard=(spoken_words or "").strip(),
                )
        if value == "no_disclosure_consent" and session.disclosure_ack is not False:
            return _fail(
                "disclosure_refusal_not_recorded",
                "Record a clear disclosure refusal before using this disposition.",
            )
        if value == "not_interested" and session.offer_accepted is not False:
            return _fail(
                "offer_decline_not_recorded",
                "Record a clear offer decline before using this disposition.",
            )
        if value == "charges_rejected" and session.charges_accepted is not False:
            return _fail(
                "charges_rejection_not_recorded",
                "Record a clear charge rejection before using this disposition.",
            )
        if value == "no_bureau_consent" and session.bureau_consent is not False:
            return _fail(
                "bureau_refusal_not_recorded",
                "Record the customer's explicit credit-bureau refusal before using this disposition.",
            )
        if value == "bureau_consent_not_obtained" and not (
            session.bureau_consent is None
            and session.bureau_consent_unclear_attempts >= 3
        ):
            return _fail(
                "bureau_consent_attempts_not_exhausted",
                (
                    "Use this outcome only after three unclear bureau-consent "
                    "answers and no explicit consent or refusal."
                ),
                attempts=session.bureau_consent_unclear_attempts,
            )
        if session.disposition is not None and session.disposition != value:
            return _fail(
                "disposition_already_set",
                "An outcome is already recorded for this call; say goodbye and stop.",
                disposition=session.disposition,
            )
        session.disposition = value
        session.touch("disposition", value, note=(note or "").strip()[:200])
        return self._commit(
            session,
            operation_id,
            _ok(
                session,
                recorded=True,
                disposition=value,
                appointment=session.appointment,
                offer=session.offer if value == "qualified_lead" else None,
            ),
        )

    def get_call_state(self, call_id: str) -> dict[str, Any]:
        session = self._session(call_id)
        if session is None:
            return _fail("unknown_call", "This call id does not exist.", call_id=call_id)
        return _ok(session, state=session.public())

    def prepare_offer_summary(self, call_id: str) -> dict[str, Any]:
        session = self._session(call_id)
        if session is None:
            return _fail("unknown_call", "This call id does not exist.", call_id=call_id)
        if (
            session.disposition != "qualified_lead"
            or session.offer is None
            or session.appointment is None
        ):
            return _fail(
                "offer_summary_not_ready",
                "The accepted offer and officer appointment must both be recorded before the final recap.",
            )
        return _ok(
            session,
            offer=session.offer,
            appointment=session.appointment,
            spoken_summary=_appointment_spoken_summary(session),
        )
